script:
(function () {
  'use strict';
  // Compound interest with end-of-month contributions. Contributions compound at the
  // effective monthly rate implied by the chosen compounding frequency:
  //   monthlyRate = (1 + r/n)^(n/12) - 1
  // Verified against closed-form values (e.g. $10,000 at 5% monthly for 10 years = $16,470.09).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function project(principal, monthly, annualRate, years, n) {
    var monthlyRate = Math.pow(1 + annualRate / n, n / 12) - 1;
    var balance = principal, contributed = principal, rows = [];
    for (var m = 1; m <= years * 12; m++) {
      balance = balance * (1 + monthlyRate) + monthly;
      contributed += monthly;
      if (m % 12 === 0) rows.push({ year: m / 12, contributed: contributed, balance: balance });
    }
    return { balance: balance, contributed: contributed, rows: rows };
  }

  function update() {
    var principal = num('ciPrincipal'), monthly = num('ciMonthly'), rate = num('ciRate'),
        years = Math.round(num('ciYears')), n = parseInt(document.getElementById('ciCompound').value, 10);
    var error = document.getElementById('ciError');
    var bad = [principal, monthly, rate, years].some(isNaN) || principal < 0 || monthly < 0 ||
              rate < 0 || rate > 100 || years < 1 || years > 100;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, a rate from 0 to 100% and 1 to 100 years.';
      return;
    }
    var r = project(principal, monthly, rate / 100, years, n);
    document.getElementById('ciFuture').textContent = money.format(r.balance);
    document.getElementById('ciContributed').textContent = money.format(r.contributed);
    document.getElementById('ciInterest').textContent = money.format(r.balance - r.contributed);
    document.getElementById('ciSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.contributed) + '</td><td>' +
             money.format(row.balance - row.contributed) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ciForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
